import os,re
def imports(f): return [m.group(1) for m in (re.match(r'import\s+(\S+)',l) for l in open(f)) if m]
def path(m): return os.path.join('.', m.replace('.','/')+'.lean')
seen=set(); q=['AlgebraicJacobian']
while q:
    m=q.pop()
